  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.form-field:last-of-type {
  margin-bottom: 0;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-indicator {
  color: var(--color-error);
